import type { OverlayProps } from "./overlay.types";
import type { CSSObject } from "@emotion/react";

import styled from "@emotion/styled";
import { keyframes } from "@emotion/react";
import { getExcludedDOMProps, getStyleSlots } from "@system";
import * as RadixDialog from "@radix-ui/react-dialog";
import { useMemo } from "react";

const componentName = "Overlay";

export const OverlayClasses = {
  root: "exp-textura_overlay",
  content: "exp-textura_overlay_content",
};

// JSS generator function
// Set up style variant settings for the component (if more than "default"), using style slots
// const getVariantConfig = (theme: Theme): ComponentStyleVariantConfig => ({
//   exampleVariant: { root: { backgroundColor: theme.color.background.default } },
// });

const generateStyles = (props: OverlayProps): CSSObject => {
  const { currentTheme: theme, variant, styleSlots: styleSlotsProp } = props;
  if (!theme) return {};

  // We are within an Emotion styled component, so we can utilize hooks
  // eslint-disable-next-line react-hooks/rules-of-hooks
  const styleSlots = useMemo(
    () =>
      getStyleSlots<OverlayProps["styleSlots"]>(
        componentName,
        theme,
        variant,
        styleSlotsProp,
        // getVariantConfig(theme),
      ),
    [theme, variant, styleSlotsProp],
  );

  const fadeIn = keyframes`from { opacity: 0; } to { opacity: 1; }`;
  const fadeOut = keyframes`from { opacity: 1; } to { opacity: 0; }`;

  return {
    [`&.${OverlayClasses.root}`]: {
      position: "fixed",
      inset: 0,
      animationTimingFunction: "ease",
      animationFillMode: "forwards",
      backgroundColor: theme.overlay.background,
      zIndex: theme.zIndex.dynamic,
      animationDuration: "150ms",
      '&[data-state="open"]': {
        animationName: fadeIn,
      },
      '&[data-state="closed"]': {
        animationName: fadeOut,
      },
      '&[data-textura-scoped="true"]': {
        position: "absolute",
      },
      ...styleSlots?.root,
    },

    [`&.${OverlayClasses.content}`]: {
      position: "fixed",
      top: "50%",
      left: "50%",
      transform: "translate(-50%, -50%)",
      opacity: 1,
      animationTimingFunction: "ease",
      animationFillMode: "forwards",
      animationDuration: "100ms",
      overflowY: "auto",
      zIndex: theme.zIndex.overlay,
      '&[data-state="open"]': {
        animationName: fadeIn,
        opacity: 1,
      },
      [`&[data-state="closed"]`]: {
        animationName: fadeOut,
      },
      "&:focus-visible": {
        outline: "none",
        boxShadow: "none",
      },
      '&[data-textura-scoped="true"]': {
        position: "absolute",
      },
      ...styleSlots?.content,
    },
  };
};

// Prevent props like `variant` from being passed to the DOM
const excludedDOMProps = getExcludedDOMProps();

export const StyledOverlay = styled("div", {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<Omit<OverlayProps, "children">>((props) => generateStyles(props));

export const StyledContent = styled(RadixDialog.Content, {
  shouldForwardProp: (prop) => !excludedDOMProps.includes(prop),
})<Omit<OverlayProps, "children">>((props) => generateStyles(props));
